  /// if (status != ML_ERROR_NONE) {
  /// // handle error case
  /// goto error;
  /// }
  ///
  /// if (node_list) {
  /// gchar *name = NULL;
  /// guint idx = 0;
  ///
  /// while ((name = node_list[idx++]) != NULL) {
  /// // node name is 'src_0' or 'src_1'
  ///
  /// // release name
  /// g_free (name);
  /// }
  /// // release list of switch pads
  /// g_free (node_list);
  /// }
  ///
  /// error:
  /// ml_pipeline_switch_release_handle (switch_handle);
