/// @brief Enumeration for tizen errors.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 2.3.1 @endif
abstract class tizen_error_e {
  /// < Successful
  static const int TIZEN_ERROR_NONE = 0;

  /// < Operation not permitted
  static const int TIZEN_ERROR_NOT_PERMITTED = -1;

  /// < No such file or directory
  static const int TIZEN_ERROR_NO_SUCH_FILE = -2;

  /// < No such process
  static const int TIZEN_ERROR_NO_SUCH_PROCESS = -3;

  /// < Interrupted system call
  static const int TIZEN_ERROR_INTERRUPTED_SYS_CALL = -4;

  /// < I/O error
  static const int TIZEN_ERROR_IO_ERROR = -5;

  /// < No such device or address
  static const int TIZEN_ERROR_NO_SUCH_DEVICE = -6;

  /// < Argument list too long
  static const int TIZEN_ERROR_ARGUMENT_LIST_TOO_LONG = -7;

  /// < Exec format error
  static const int TIZEN_ERROR_EXEC_FORMAT_ERROR = -8;

  /// < Bad file number
  static const int TIZEN_ERROR_BAD_FILE_NUMBER = -9;

  /// < Try again
  static const int TIZEN_ERROR_TRY_AGAIN = -11;

  /// < Out of memory
  static const int TIZEN_ERROR_OUT_OF_MEMORY = -12;

  /// < Permission denied
  static const int TIZEN_ERROR_PERMISSION_DENIED = -13;

  /// < Bad address
  static const int TIZEN_ERROR_BAD_ADDRESS = -14;

  /// < Block device required
  static const int TIZEN_ERROR_BLOCK_DEVICE_REQUIRED = -15;

  /// < Device or resource busy
  static const int TIZEN_ERROR_RESOURCE_BUSY = -16;

  /// < File exists
  static const int TIZEN_ERROR_FILE_EXISTS = -17;

  /// < Cross-device link
  static const int TIZEN_ERROR_CROSS_DEVICE_LINK = -18;

  /// < Not a directory
  static const int TIZEN_ERROR_NOT_A_DIRECTORY = -20;

  /// < Is a directory
  static const int TIZEN_ERROR_IS_A_DIRECTORY = -21;

  /// < Invalid function parameter
  static const int TIZEN_ERROR_INVALID_PARAMETER = -22;

  /// < File table overflow
