/// @brief Enumeration for job error.
/// @since_tizen 4.0
abstract class job_error_e {
  /// < Successful
  static const int JOB_ERROR_NONE = 0;

  /// < Invalid parameter
  static const int JOB_ERROR_INVALID_PARAMETER = -22;

  /// < Out of memory
  static const int JOB_ERROR_OUT_OF_MEMORY = -12;

  /// < IO error
  static const int JOB_ERROR_IO_ERROR = -5;

  /// < Not initialized
  static const int JOB_ERROR_NOT_INITIALIZED = -49938399;

  /// < No such job
  static const int JOB_ERROR_NO_SUCH_JOB = -49938398;

  /// < Already exist
  static const int JOB_ERROR_ALREADY_EXIST = -49938397;

  /// < Permission denied
