/// @brief Enumeration for buffer deallocation policies.
/// @since_tizen 5.5
abstract class ml_pipeline_buf_policy_e {
  /// < Default. Application should not deallocate this buffer. NNStreamer will deallocate when the buffer is no more needed.
  static const int ML_PIPELINE_BUF_POLICY_AUTO_FREE = 0;

  /// < This buffer is not to be freed by NNStreamer (i.e., it's a static object). However, be careful: NNStreamer might be accessing this object after the return of the API call.
  static const int ML_PIPELINE_BUF_POLICY_DO_NOT_FREE = 1;

  /// < Max size of #ml_pipeline_buf_policy_e structure.
  static const int ML_PIPELINE_BUF_POLICY_MAX = 2;

  /// < Trigger End-Of-Stream event for the corresponding appsrc and ignore the given input value. The corresponding appsrc will no longer accept new data after this.
  static const int ML_PIPELINE_BUF_SRC_EVENT_EOS = 65536;
}

/// @brief Enumeration for pipeline state.
