  static const int ML_PIPELINE_STATE_READY = 2;

  /// < GST-State "Paused"
  static const int ML_PIPELINE_STATE_PAUSED = 3;

  /// < GST-State "Playing"
  static const int ML_PIPELINE_STATE_PLAYING = 4;
}

