  /// < No such file
  static const int IMAGE_UTIL_ERROR_NO_SUCH_FILE = -2;

  /// < Internal error
  static const int IMAGE_UTIL_ERROR_INVALID_OPERATION = -38;

  /// < Not supported format
  static const int IMAGE_UTIL_ERROR_NOT_SUPPORTED_FORMAT = -26345471;

  /// < Permission denied
  static const int IMAGE_UTIL_ERROR_PERMISSION_DENIED = -13;

  /// < Not supported
  static const int IMAGE_UTIL_ERROR_NOT_SUPPORTED = -1073741822;
}

