  /// < Not supported
  static const int MEDIAEDITOR_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Internal error
  static const int MEDIAEDITOR_ERROR_INVALID_OPERATION = -38;

  /// < Invalid parameter
  static const int MEDIAEDITOR_ERROR_INVALID_PARAMETER = -22;

  /// < The access to the resources can not be granted
  static const int MEDIAEDITOR_ERROR_PERMISSION_DENIED = -13;

  /// < Invalid state
  static const int MEDIAEDITOR_ERROR_INVALID_STATE = -51183615;

  /// < Blocked by resource conflicted
  static const int MEDIAEDITOR_ERROR_RESOURCE_CONFLICT = -51183614;

  /// < Blocked by resource failed
  static const int MEDIAEDITOR_ERROR_RESOURCE_FAILED = -51183613;
}

