/// @brief Enumeration for the effect type.
/// @since_tizen 7.0
/// @remarks #MEDIAEDITOR_EFFECT_AUDIO_TYPE_FADE_IN and #MEDIAEDITOR_EFFECT_AUDIO_TYPE_FADE_OUT Can not be rolled back *
abstract class mediaeditor_effect_type_e {
  /// < None
  static const int MEDIAEDITOR_EFFECT_TYPE_NONE = 0;

  /// < Applies edge detect on video
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_EDGETV = 1;

  /// < Adds age to video input using scratches and dust
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_AGINGTV = 2;

  /// < Dices the screen up into many small squares
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_DICETV = 3;

  /// < Realtime goo'ing of the video input
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_WARPTV = 4;

  /// < Makes images shagadelic
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_SHAGADELICTV = 5;

  /// < A loopback alpha blending effector with rotating and scaling
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_VERTIGOTV = 6;

  /// < A video waveform monitor for each line of video processed
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_REVTV = 7;

  /// < Motion dissolver
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_QUARKTV = 8;

  /// < Optical art meets real-time video effect
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_OPTV = 9;

  /// < Detects a difference from previous frame and blurs it
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_RADIOACTV = 10;

  /// < Makes after images of moving objects
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_STREAKTV = 11;

  /// < Makes ripple mark effect on the video input
  static const int MEDIAEDITOR_EFFECT_VIDEO_TYPE_RIPPLETV = 12;

  /// < Audio fade in
  static const int MEDIAEDITOR_EFFECT_AUDIO_TYPE_FADE_IN = 13;

  /// < Audio fade out
  static const int MEDIAEDITOR_EFFECT_AUDIO_TYPE_FADE_OUT = 14;

  /// < Adds an echo or reverb effect to an audio stream
  static const int MEDIAEDITOR_EFFECT_AUDIO_TYPE_ECHO = 15;
}

