/// @brief Enumeration for media player state.
/// @since_tizen @if WEARABLE 2.3.1 @else 2.3 @endif
abstract class player_state_e {
  /// < Player is not created
  static const int PLAYER_STATE_NONE = 0;

  /// < Player is created, but not prepared
  static const int PLAYER_STATE_IDLE = 1;

  /// < Player is ready to play media
  static const int PLAYER_STATE_READY = 2;

  /// < Player is playing media
  static const int PLAYER_STATE_PLAYING = 3;

  /// < Player is paused while playing media
  static const int PLAYER_STATE_PAUSED = 4;
}

/// @brief Enumeration for media player's error codes.
/// @since_tizen @if WEARABLE 2.3.1 @else 2.3 @endif
abstract class player_error_e {
  /// < Successful
  static const int PLAYER_ERROR_NONE = 0;

  /// < Out of memory
  static const int PLAYER_ERROR_OUT_OF_MEMORY = -12;

  /// < Invalid parameter
  static const int PLAYER_ERROR_INVALID_PARAMETER = -22;

  /// < No such file or directory
  static const int PLAYER_ERROR_NO_SUCH_FILE = -2;

  /// < Invalid operation
  static const int PLAYER_ERROR_INVALID_OPERATION = -38;

  /// < No space left on the device
  static const int PLAYER_ERROR_FILE_NO_SPACE_ON_DEVICE = -28;

  /// < Not supported Feature
  static const int PLAYER_ERROR_FEATURE_NOT_SUPPORTED_ON_DEVICE = -1073741822;

  /// < Seek operation failure
  static const int PLAYER_ERROR_SEEK_FAILED = -26476511;

  /// < Invalid state
  static const int PLAYER_ERROR_INVALID_STATE = -26476510;

  /// < File format not supported
  static const int PLAYER_ERROR_NOT_SUPPORTED_FILE = -26476509;

  /// < Invalid URI
  static const int PLAYER_ERROR_INVALID_URI = -26476508;

  /// < Sound policy error
  static const int PLAYER_ERROR_SOUND_POLICY = -26476507;

  /// < Streaming connection failed
  static const int PLAYER_ERROR_CONNECTION_FAILED = -26476506;

  /// < Video capture failed
  static const int PLAYER_ERROR_VIDEO_CAPTURE_FAILED = -26476505;

  /// < Expired license
  static const int PLAYER_ERROR_DRM_EXPIRED = -26476504;

  /// < No license
  static const int PLAYER_ERROR_DRM_NO_LICENSE = -26476503;

  /// < License for future use
  static const int PLAYER_ERROR_DRM_FUTURE_USE = -26476502;

  /// < Format not permitted
  static const int PLAYER_ERROR_DRM_NOT_PERMITTED = -26476501;

  /// < Resource limit
  static const int PLAYER_ERROR_RESOURCE_LIMIT = -26476500;

  /// < Permission denied
  static const int PLAYER_ERROR_PERMISSION_DENIED = -13;

  /// < Socket connection lost (Since 3.0)
  static const int PLAYER_ERROR_SERVICE_DISCONNECTED = -26476499;

  /// < No buffer space available (Since 3.0)
  static const int PLAYER_ERROR_BUFFER_SPACE = -105;

  /// < Not supported audio codec but video can be played (Since 4.0)
  static const int PLAYER_ERROR_NOT_SUPPORTED_AUDIO_CODEC = -26476498;

  /// < Not supported video codec but audio can be played (Since 4.0)
  static const int PLAYER_ERROR_NOT_SUPPORTED_VIDEO_CODEC = -26476497;

  /// < Not supported subtitle format (Since 4.0)
  static const int PLAYER_ERROR_NOT_SUPPORTED_SUBTITLE = -26476496;

  /// < Not supported format (Since 5.5)
  static const int PLAYER_ERROR_NOT_SUPPORTED_FORMAT = -26476495;

  /// < Not available operation (Since 5.5)
  static const int PLAYER_ERROR_NOT_AVAILABLE = -26476494;
}

/// @brief Enumeration for media player's interruption type.
/// @since_tizen @if WEARABLE 2.3.1 @else 2.3 @endif
abstract class player_interrupted_code_e {
  /// < Interrupted by a resource conflict and the player handle will be paused or unprepared
  static const int PLAYER_INTERRUPTED_BY_RESOURCE_CONFLICT = 4;
}

/// @brief Enumeration for display type.
/// @since_tizen @if WEARABLE 2.3.1 @else 2.3 @endif
/// @details In case of using #PLAYER_DISPLAY_TYPE_OVERLAY_SYNC_UI, the video is rendering in full scale in the rendering area.\n
/// To change the video rendering position, use UI API functions like ecore_wl2_subsurface_exported_surface_move(),
/// ecore_wl2_subsurface_exported_surface_resize(), ecore_wl2_subsurface_exported_surface_transform_set(),
/// ecore_wl2_subsurface_exported_surface_show() and ecore_wl2_subsurface_exported_surface_commit().\n
/// player_set_display_mode(), player_set_display_rotation() and player_set_display_roi_area() cannot be used and
/// #PLAYER_ERROR_NOT_AVAILABLE is returned if they are used.\n
/// Exported shell handle must be obtained by ecore_wl2_subsurface_exported_surface_handle_get() from Ecore_Wl2_Subsurface.\n
/// Then the exported shell handle should be set with player_set_display().\n
/// To render the first video buffer, commit by ecore_wl2_window_commit() after player_prepare() of Ecore_Wl2_Subsurface.\n
/// Always commit with ecore_wl2_window_commit() with parent surface when the UI changes and the video needs to be synchronized.
abstract class player_display_type_e {
  /// < Overlay surface display
  static const int PLAYER_DISPLAY_TYPE_OVERLAY = 0;

  /// < Evas image object surface display (Since 4.0)
  static const int PLAYER_DISPLAY_TYPE_EVAS = 3;

  /// < This disposes of buffers (Since 4.0)
  static const int PLAYER_DISPLAY_TYPE_NONE = 4;

  /// < Overlay surface display for synchronization between UI and video (Since 6.5)
  static const int PLAYER_DISPLAY_TYPE_OVERLAY_SYNC_UI = 5;
}

/// @brief Enumeration for audio latency mode.
/// @since_tizen @if WEARABLE 2.3.1 @else 2.3 @endif
abstract class audio_latency_mode_e {
  /// < Low audio latency mode
  static const int AUDIO_LATENCY_MODE_LOW = 0;

