/// @brief The structure type for statistics property information.
/// @since_tizen 7.0
final class webrtc_stats_prop_info_s extends ffi.Struct {
  /// < The property name
  external ffi.Pointer<ffi.Char> name;

  /// < The property enum
  @ffi.Int32()
  external int prop;

  /// < The property data type
  @ffi.Int32()
  external int type;

  /// The property value as per the data type above
  external UnnamedUnion2 unnamed;
}

/// The property value as per the data type above
final class UnnamedUnion2 extends ffi.Union {
  /// < For boolean
  @ffi.Bool()
  external bool v_bool;

  /// < For signed integer
  @ffi.Int()
  external int v_int;

  /// < For unsigned integer
  @ffi.UnsignedInt()
  external int v_uint;

  /// < For 64-bit signed integer
  @ffi.Int64()
  external int v_int64;

  /// < For 64-bit unsigned integer
  @ffi.Uint64()
  external int v_uint64;

  /// < For float
  @ffi.Float()
  external double v_float;

  /// < For double
  @ffi.Double()
  external double v_double;

  /// < For string
  external ffi.Pointer<ffi.Char> v_string;
}

