/// @brief Called iteratively to report all the statistics properties.
/// @since_tizen 7.0
/// @remarks The @a prop_info can be used only in the callback. To use outside, make a copy.
/// @param[in] type       The statistics type
/// @param[in] prop_info  The statistics property information
/// @param[in] user_data  The user data passed from the callback registration function
/// @return @c true to continue with the next iteration of the loop,
/// otherwise @c false to break out of the loop
/// @see webrtc_foreach_stats()
/// @par Example
/// @code
/// bool __stats_cb(webrtc_stats_type_e type, const webrtc_stats_prop_info_s *prop_info, void *user_data)
/// {
/// switch (prop_info->type) {
/// case WEBRTC_STATS_PROP_TYPE_BOOL:
/// printf("type[0x%x] prop[%s, 0x%08x, value:%d]\n", type, prop_info->name, prop_info->prop, prop_info->v_bool);
/// break;
/// case WEBRTC_STATS_PROP_TYPE_INT:
/// printf("type[0x%x] prop[%s, 0x%08x, value:%d]\n", type, prop_info->name, prop_info->prop, prop_info->v_int);
/// break;
/// case WEBRTC_STATS_PROP_TYPE_INT64:
/// printf("type[0x%x] prop[%s, 0x%08x, value:%"PRId64"]\n", type, prop_info->name, prop_info->prop, prop_info->v_int64);
/// break;
/// case WEBRTC_STATS_PROP_TYPE_UINT:
/// printf("type[0x%x] prop[%s, 0x%08x, value:%u]\n", type, prop_info->name, prop_info->prop, prop_info->v_uint);
/// break;
/// case WEBRTC_STATS_PROP_TYPE_UINT64:
/// printf("type[0x%x] prop[%s, 0x%08x, value:%"PRIu64"]\n", type, prop_info->name, prop_info->prop, prop_info->v_uint64);
/// break;
/// case WEBRTC_STATS_PROP_TYPE_FLOAT:
/// printf("type[0x%x] prop[%s, 0x%08x, value:%f]\n", type, prop_info->name, prop_info->prop, prop_info->v_float);
/// break;
/// case WEBRTC_STATS_PROP_TYPE_DOUBLE:
/// printf("type[0x%x] prop[%s, 0x%08x, value:%lf]\n", type, prop_info->name, prop_info->prop, prop_info->v_double);
/// break;
/// case WEBRTC_STATS_PROP_TYPE_STRING:
/// printf("type[0x%x] prop[%s, 0x%08x, value:%s]\n", type, prop_info->name, prop_info->prop, prop_info->v_string);
/// break;
/// }
/// return true;
/// }
/// @endcode
typedef webrtc_stats_cb
    = ffi.Pointer<ffi.NativeFunction<webrtc_stats_cbFunction>>;
typedef webrtc_stats_cbFunction = ffi.Bool Function(
    ffi.Int32 type,
    ffi.Pointer<webrtc_stats_prop_info_s> prop_info,
    ffi.Pointer<ffi.Void> user_data);
typedef Dartwebrtc_stats_cbFunction = bool Function(
    int type,
    ffi.Pointer<webrtc_stats_prop_info_s> prop_info,
    ffi.Pointer<ffi.Void> user_data);

/// @brief Enumeration for Application Service Platform (ASP) error code.
/// @since_tizen 4.0
abstract class asp_error_e {
  /// < Successful
  static const int ASP_ERROR_NONE = 0;

  /// < Operation not permitted(1)
  static const int ASP_ERROR_NOT_PERMITTED = -1;

  /// < Out of memory(12)
  static const int ASP_ERROR_OUT_OF_MEMORY = -12;

  /// < Permission denied(13)
  static const int ASP_ERROR_PERMISSION_DENIED = -13;

  /// < Device or resource busy(16)
  static const int ASP_ERROR_RESOURCE_BUSY = -16;

  /// < Invalid function parameter(22)
  static const int ASP_ERROR_INVALID_PARAMETER = -22;

  /// < Connection timed out(110)
  static const int ASP_ERROR_CONNECTION_TIME_OUT = -110;

  /// < Not supported
  static const int ASP_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Not initialized
  static const int ASP_ERROR_NOT_INITIALIZED = -49676287;

  /// < Already initialized
  static const int ASP_ERROR_ALREADY_INITIALIZED = -49676286;

  /// < I/O error
  static const int ASP_ERROR_COMMUNICATION_FAILED = -49676285;

  /// < Operation failed
  static const int ASP_ERROR_OPERATION_FAILED = -49676284;

  /// < In progress
  static const int ASP_ERROR_IN_PROGRESS = -49676283;

  /// < Service not found
  static const int ASP_ERROR_SERVICE_NOT_FOUND = -49676282;

  /// < Session not found
  static const int ASP_ERROR_SESSION_NOT_FOUND = -49676281;

  /// < Requested network role rejected
  static const int ASP_ERROR_NETWORK_ROLE_REJECTED = -49676280;
}

/// @brief Enumeration for Advertise Status event reason.
/// @since_tizen 4.0
abstract class asp_advert_status_reason_e {
  /// < Status reason: Success
  static const int ASP_ADVERT_STATUS_REASON_SUCCESS = 0;

  /// < Status reason: Service duplicated
  static const int ASP_ADVERT_STATUS_REASON_SERVICE_DUPLICATED = 1;

  /// < Status reason: Other failure
  static const int ASP_ADVERT_STATUS_REASON_OTHER_FAILURE = 2;
}

/// @brief Enumeration for the Wi-Fi P2P role assignment scheme.
/// @since_tizen 4.0
/// @see asp_advert_set_p2p_role_scheme()
/// @see asp_advert_get_p2p_role_scheme()
/// @see asp_session_set_p2p_role_scheme()
/// @see asp_session_get_p2p_role_scheme()
abstract class asp_advert_p2p_role_scheme_e {
  /// < All roles are acceptable
  static const int ASP_ADVERT_P2P_ROLE_SCHEME_ANY = 0;

  /// < The interface should assume the GO role
  static const int ASP_ADVERT_P2P_ROLE_SCHEME_GO = 1;

  /// < The interface should assume the GC role
  static const int ASP_ADVERT_P2P_ROLE_SCHEME_GC = 2;
}

/// @brief Enumeration for service discovery mechanism.
/// @since_tizen 4.0
/// @see asp_advert_set_discovery_tech()
/// @see asp_seek_set_discovery_tech()
abstract class asp_discovery_tech_e {
  /// < Use Wi-Fi P2P for discovery mechanism
  static const int ASP_DISCOVERY_TECH_P2P = 1;

  /// < Use BLE for discovery mechanism
  static const int ASP_DISCOVERY_TECH_BLE = 2;

  /// < Use NFC for discovery mechanism
  static const int ASP_DISCOVERY_TECH_NFC = 4;

  /// < Use Wi-Fi Infrastructured for discovery mechanism
  static const int ASP_DISCOVERY_TECH_INFRA = 8;

  /// < Use Wi-Fi NAN for discovery mechanism
  static const int ASP_DISCOVERY_TECH_NAN = 16;
}

/// @brief Enumeration for Wi-Fi WPS type.
/// @see asp_advert_set_p2p_config_method()
/// @see asp_advert_get_p2p_config_method()
/// @see asp_session_set_p2p_config_method()
/// @see asp_session_get_p2p_config_method()
/// @since_tizen 4.0
abstract class asp_wps_type_e {
  /// < No WPS type
  static const int ASP_WPS_TYPE_NONE = 0;

  /// < Default WPS type both P2PS and PIN
  static const int ASP_WPS_TYPE_DEFAULT = 1;

  /// < WPS type PIN code both display and keypad
  static const int ASP_WPS_TYPE_PIN_BOTH = 2;

  /// < WPS type display PIN code only
  static const int ASP_WPS_TYPE_PIN_DISPLAY = 3;

  /// < WPS type keypad to input the PIN only
  static const int ASP_WPS_TYPE_PIN_KEYPAD = 4;
}

/// @brief Enumeration for Application Service Platform (ASP) Session connect status.
/// @since_tizen 4.0
abstract class asp_connect_status_e {
  /// < Network role rejected
  static const int ASP_CONNECT_STATUS_NETWORK_ROLE_REJECTED = 0;

  /// < The device's connection limit has been reached
  static const int ASP_CONNECT_STATUS_CONNECTION_LIMIT_REACHED = 1;

  /// < Session request sent
  static const int ASP_CONNECT_STATUS_REQUEST_SENT = 2;

  /// < Session request received
  static const int ASP_CONNECT_STATUS_REQUEST_RECEIVED = 3;

  /// < Session request deferred
  static const int ASP_CONNECT_STATUS_REQUEST_DEFERRED = 4;

  /// < Session request accepted
  static const int ASP_CONNECT_STATUS_REQUEST_ACCEPTED = 5;

  /// < Session request failed
  static const int ASP_CONNECT_STATUS_REQUEST_FAILED = 6;

  /// < Group formation started
  static const int ASP_CONNECT_STATUS_GROUP_FORMATION_STARTED = 7;

  /// < Group formation completed
  static const int ASP_CONNECT_STATUS_GROUP_FORMATION_COMPLETED = 8;

  /// < Group formation failed
  static const int ASP_CONNECT_STATUS_GROUP_FORMATION_FAILED = 9;
}

/// @brief Enumeration for Application Service Platform (ASP) general session state.
/// @since_tizen 4.0
abstract class asp_session_state_e {
  /// < Session state error
  static const int ASP_SESSION_STATE_ERROR = 0;

  /// < Session state closed
  static const int ASP_SESSION_STATE_CLOSED = 1;

  /// < Session state initiated
  static const int ASP_SESSION_STATE_INITIATED = 2;

  /// < Session state requested
  static const int ASP_SESSION_STATE_REQUESTED = 3;

  /// < Session state open
  static const int ASP_SESSION_STATE_OPEN = 4;
}

/// @brief Enumeration for Application Service Platform (ASP) session close status.
/// @since_tizen 4.0
abstract class asp_session_close_status_e {
  /// < Session closed without error
  static const int ASP_SESSION_CLOSE_OK = 0;

  /// < Session closed by disassociation (Wi-Fi Direct connection was broken)
  static const int ASP_SESSION_CLOSE_DISASSOCIATED = 1;

  /// < Session closed with local close
  static const int ASP_SESSION_CLOSE_LOCAL_CLOSE = 2;

  /// < Session closed with remote close
  static const int ASP_SESSION_CLOSE_REMOTE_CLOSE = 3;

  /// < Session closed with system failure
  static const int ASP_SESSION_CLOSE_SYSTEM_FAILURE = 4;

  /// < Session closed with no response from remote
  static const int ASP_SESSION_CLOSE_NO_RESPONSE = 5;
}

/// @brief Enumeration for Application Service Platform (ASP) port status.
/// @since_tizen 4.0
abstract class asp_port_status_e {
  /// < Incoming connections are allowed on this local port for this ASP session
  static const int ASP_PORT_STATUS_LOCAL_PORT_ALLOWED = 0;

  /// < Incoming connections are no longer allowed in the ASP session for this local port
  static const int ASP_PORT_STATUS_LOCAL_PORT_BLOCKED = 1;

  /// < The ASP was unable to set up this local port
  static const int ASP_PORT_STATUS_FAILURE = 2;

  /// < The remote service has allowed access to the given remote port for the given protocol
  static const int ASP_PORT_STATUS_REMOTE_PORT_ALLOWED = 3;
}

/// @brief Enumeration for service status.
/// @since_tizen 4.0
abstract class asp_service_status_e {
  /// < Service status not advertised
  static const int ASP_SERVICE_STATUS_NOT_ADVERTISED = 0;

  /// < Service status advertised
  static const int ASP_SERVICE_STATUS_ADVERTISED = 1;
}

