    ffi.Double upload_now,
    ffi.Pointer<ffi.Void> user_data);
typedef Darthttp_transaction_progress_cbFunction = void Function(
    http_transaction_h http_transaction,
    double download_total,
    double download_now,
    double upload_total,
    double upload_now,
    ffi.Pointer<ffi.Void> user_data);

