  static const int INM_WLAN_STATUS_NOT_SUPPORTED_AUTH_ALG = 13;

  /// Association denied because AP is unable to handle additional
  /// associated STAs
  static const int INM_WLAN_STATUS_AP_UNABLE_TO_HANDLE_NEW_STA = 17;

  /// Association denied because the requesting STA does not support
  /// HT feature
  static const int INM_WLAN_STATUS_ASSOC_DENIED_NO_HT = 27;

  /// Association request rejected temporarily
  static const int INM_WLAN_STATUS_ASSOC_REJECTED_TEMPORARILY = 30;

  /// Robust management frame policy violation
  static const int INM_WLAN_STATUS_ROBUST_MGMT_FRAME_POLICY_VIOLATION = 31;

  /// Invalid element
  static const int INM_WLAN_STATUS_INVALID_IE = 40;

  /// Invalid group cipher
  static const int INM_WLAN_STATUS_GROUP_CIPHER_NOT_VALID = 41;

  /// Invalid pairwise cipher
  static const int INM_WLAN_STATUS_PAIRWISE_CIPHER_NOT_VALID = 42;

  /// Invalid AKMP
  static const int INM_WLAN_STATUS_AKMP_NOT_VALID = 43;

  /// Cipher suite rejected because of security policy
  static const int INM_WLAN_STATUS_CIPHER_REJECTED_PER_POLICY = 46;

  /// Association denied because the Listen interval is too large
  static const int INM_WLAN_STATUS_ASSOC_DENIED_LISTEN_INT_TOO_LARGE = 51;

  /// Invalid pairwise master key identifier (PKMID)
  static const int INM_WLAN_STATUS_INVALID_PMKID = 53;

  /// Invalid MDE
  static const int INM_WLAN_STATUS_INVALID_MDIE = 54;

  /// Invalid FTE
  static const int INM_WLAN_STATUS_INVALID_FTIE = 55;

  /// Association denied because the requesting STA does not support
  /// VHT feature
  static const int INM_WLAN_STATUS_ASSOC_DENIED_NO_VHT = 104;
}

