  static const int INM_LINK_ROUTE_TYPE_UNICAST = 1;

  /// Accept locally
  static const int INM_LINK_ROUTE_TYPE_LOCAL = 2;

  /// Accept locally as broadcast, send as broadcast
  static const int INM_LINK_ROUTE_TYPE_BROADCAST = 3;

  /// Accept locally as broadcast, but send as unicast
  static const int INM_LINK_ROUTE_TYPE_ANYCAST = 4;

  /// Multicast
  static const int INM_LINK_ROUTE_TYPE_MULTICAST = 5;

  /// Drop
  static const int INM_LINK_ROUTE_TYPE_BLACKHOLE = 6;

  /// Destination is unreachable
  static const int INM_LINK_ROUTE_TYPE_UNREACHABLE = 7;

  /// Administratively prohibited
  static const int INM_LINK_ROUTE_TYPE_PROHIBIT = 8;

  /// Not in this table
  static const int INM_LINK_ROUTE_TYPE_THROW = 9;

  /// Translate this address
  static const int INM_LINK_ROUTE_TYPE_NAT = 10;

  /// Use external resolver
  static const int INM_LINK_ROUTE_TYPE_XRESOLVE = 11;
}

