/// @brief Enumeration for type of observation.
/// @since_tizen 3.0
abstract class iotcon_observe_type_e {
  /// < Indicates no option
  static const int IOTCON_OBSERVE_NO_TYPE = 0;

  /// < Indicates action of registering observation
  static const int IOTCON_OBSERVE_REGISTER = 1;

  /// < Indicates action of unregistering observation
  static const int IOTCON_OBSERVE_DEREGISTER = 2;
}

/// @brief Enumeration for policy of observation.
/// @since_tizen 3.0
abstract class iotcon_observe_policy_e {
  /// < Indicates observation request for most up-to-date notifications only
  static const int IOTCON_OBSERVE_IGNORE_OUT_OF_ORDER = 0;

  /// < Indicates observation request for all notifications including state notifications
  static const int IOTCON_OBSERVE_ACCEPT_OUT_OF_ORDER = 1;
}

/// @brief Enumeration for connectivities which can be held in a resource.
/// @remarks IOTCON_CONNECTIVITY_PREFER_UDP and IOTCON_CONNECTIVITY_PREFER_TCP should be mutually exclusive.
/// @remarks IOTCON_CONNECTIVITY_IPV4_ONLY and IOTCON_CONNECTIVITY_IPV6_ONLY should be mutually exclusive.
/// @since_tizen 3.0
abstract class iotcon_connectivity_type_e {
  /// < Indicates all connectivities
  static const int IOTCON_CONNECTIVITY_ALL = 0;

  /// < Indicates Internet Protocol connectivity
  static const int IOTCON_CONNECTIVITY_IP = 1;

  /// < It is related to IOTCON_CONNECTIVITY_IP, and it indicates UDP is preferred
  static const int IOTCON_CONNECTIVITY_PREFER_UDP = 65536;

  /// < It is related to IOTCON_CONNECTIVITY_IP, and it indicates TCP is preferred
  static const int IOTCON_CONNECTIVITY_PREFER_TCP = 131072;

  /// < When this bit is set with IOTCON_CONNECTIVITY_IP, resources are discovered for IPv4
  static const int IOTCON_CONNECTIVITY_IPV4_ONLY = 262144;

  /// < When this bit is set with IOTCON_CONNECTIVITY_IP, resources are discovered for IPv6
  static const int IOTCON_CONNECTIVITY_IPV6_ONLY = 524288;
}

/// @brief Enumeration for policy which can be held in a resource.
/// @since_tizen 3.0
abstract class iotcon_resource_policy_e {
  /// < Indicates resource uninitialized
  static const int IOTCON_RESOURCE_NO_POLICY = 0;

  /// < Indicates resource that is allowed to be discovered
  static const int IOTCON_RESOURCE_DISCOVERABLE = 1;

  /// < Indicates resource that is allowed to be observed
  static const int IOTCON_RESOURCE_OBSERVABLE = 2;

  /// < Indicates resource initialized and activated
  static const int IOTCON_RESOURCE_ACTIVE = 4;

  /// < Indicates resource which takes some delay to respond
  static const int IOTCON_RESOURCE_SLOW = 8;

  /// < Indicates secure resource
  static const int IOTCON_RESOURCE_SECURE = 16;

  /// < When this bit is set, the resource is allowed to be discovered only if discovery request contains an explicit querystring.
  static const int IOTCON_RESOURCE_EXPLICIT_DISCOVERABLE = 32;
}

/// @brief Enumeration for type of request.
/// @since_tizen 3.0
abstract class iotcon_request_type_e {
  /// < Indicates none
  static const int IOTCON_REQUEST_UNKNOWN = 0;

  /// < Indicates get method of request
  static const int IOTCON_REQUEST_GET = 1;

  /// < Indicates put method of request
  static const int IOTCON_REQUEST_PUT = 2;

  /// < Indicates post method of request
  static const int IOTCON_REQUEST_POST = 3;

  /// < Indicates delete method of request
  static const int IOTCON_REQUEST_DELETE = 4;
}

/// @brief Enumeration for result of response.
/// @since_tizen 3.0
abstract class iotcon_response_result_e {
  /// < Indicates result of response for success
  static const int IOTCON_RESPONSE_OK = 0;

  /// < Indicates result of response for error
  static const int IOTCON_RESPONSE_ERROR = 1;

  /// < Indicates result of response for resource creation
  static const int IOTCON_RESPONSE_RESOURCE_CREATED = 2;

  /// < Indicates result of response for resource deletion
  static const int IOTCON_RESPONSE_RESOURCE_DELETED = 3;

  /// < Indicates result of response for resource change
  static const int IOTCON_RESPONSE_RESOURCE_CHANGED = 4;

  /// < Indicates result of response for slow resource
  static const int IOTCON_RESPONSE_SLOW = 5;

  /// < Indicates result of response for accessing unauthorized resource
  static const int IOTCON_RESPONSE_FORBIDDEN = 6;
}

/// @brief Enumeration for result of presence.
/// @since_tizen 3.0
abstract class iotcon_presence_result_e {
  /// < Indicates for successful action of presence
  static const int IOTCON_PRESENCE_OK = 0;

  /// < Indicates for stopped action of presence
  static const int IOTCON_PRESENCE_STOPPED = 1;

  /// < Indicates for no response of presence for some time
  static const int IOTCON_PRESENCE_TIMEOUT = 2;
}

/// @brief Enumeration for operation of presence response.
/// @since_tizen 3.0
abstract class iotcon_presence_trigger_e {
  /// < Indicates for resource creation operation of server
  static const int IOTCON_PRESENCE_RESOURCE_CREATED = 0;

  /// < Indicates for resource update operation of server
  static const int IOTCON_PRESENCE_RESOURCE_UPDATED = 1;

  /// < Indicates for resource destruction operation of server
  static const int IOTCON_PRESENCE_RESOURCE_DESTROYED = 2;
}

/// @brief Enumeration for types of representation that is possible to have.
/// @since_tizen 3.0
abstract class iotcon_type_e {
  /// < Indicates for representation that have no type
  static const int IOTCON_TYPE_NONE = 0;

  /// < Indicates for representation that have int type
  static const int IOTCON_TYPE_INT = 1;

  /// < Indicates for representation that have bool type
  static const int IOTCON_TYPE_BOOL = 2;

  /// < Indicates for representation that have double type
  static const int IOTCON_TYPE_DOUBLE = 3;

  /// < Indicates for representation that have string type
  static const int IOTCON_TYPE_STR = 4;

  /// < Indicates for representation that have byte string type
  static const int IOTCON_TYPE_BYTE_STR = 5;

  /// < Indicates for representation that have null type
  static const int IOTCON_TYPE_NULL = 6;

  /// < Indicates for representation that have list type
  static const int IOTCON_TYPE_LIST = 7;

  /// < Indicates for representation that have another representation type
  static const int IOTCON_TYPE_ATTRIBUTES = 8;
}

/// @brief Enumeration for properties of device information.
/// @since_tizen 3.0
abstract class iotcon_device_info_e {
  /// < Indicates human friendly name for device
  static const int IOTCON_DEVICE_INFO_NAME = 0;

  /// < Indicates spec version of the core specification
  static const int IOTCON_DEVICE_INFO_SPEC_VER = 1;

  /// < Indicates unique identifier for OCF device
  static const int IOTCON_DEVICE_INFO_ID = 2;

  /// < Indicates version of the specs this device data model is implemented to
  static const int IOTCON_DEVICE_INFO_DATA_MODEL_VER = 3;
}

/// @brief Enumeration for properties of platform information.
/// @since_tizen 3.0
abstract class iotcon_platform_info_e {
  /// < Indicates platform identifier
  static const int IOTCON_PLATFORM_INFO_ID = 0;

  /// < Indicates name of manufacturer
  static const int IOTCON_PLATFORM_INFO_MANUF_NAME = 1;

  /// < Indicates URL to manufacturer
  static const int IOTCON_PLATFORM_INFO_MANUF_URL = 2;

  /// < Indicates model number as designated by manufacturer
  static const int IOTCON_PLATFORM_INFO_MODEL_NUMBER = 3;

  /// < Indicates manufacturing date of device
  static const int IOTCON_PLATFORM_INFO_DATE_OF_MANUF = 4;

  /// < Indicates version of platform defined by manufacturer
  static const int IOTCON_PLATFORM_INFO_PLATFORM_VER = 5;

  /// < Indicates version of platform resident OS
  static const int IOTCON_PLATFORM_INFO_OS_VER = 6;

  /// < Indicates version of platform hardware
  static const int IOTCON_PLATFORM_INFO_HARDWARE_VER = 7;

  /// < Indicates version of device firmware
  static const int IOTCON_PLATFORM_INFO_FIRMWARE_VER = 8;

  /// < Indicates URL that points to support information from manufacturer
  static const int IOTCON_PLATFORM_INFO_SUPPORT_URL = 9;

  /// < Indicates reference time for the device
  static const int IOTCON_PLATFORM_INFO_SYSTEM_TIME = 10;
}

/// @brief Enumeration for states of remote resource.
/// @since_tizen 3.0
abstract class iotcon_remote_resource_state_e {
  /// < Indicates remote resource is alive
  static const int IOTCON_REMOTE_RESOURCE_ALIVE = 0;

  /// < Indicates remote resource is lost
  static const int IOTCON_REMOTE_RESOURCE_LOST_SIGNAL = 1;
}

/// @brief Enumeration for quality of service.
/// @since_tizen 3.0
abstract class iotcon_qos_e {
  /// < Indicates low quality of service
  static const int IOTCON_QOS_LOW = 0;

  /// < Indicates high quality of service
  static const int IOTCON_QOS_HIGH = 1;
}

