/// @partner
/// @brief Enumeration for CSR Errors.
/// @since_tizen 3.0
abstract class csr_error_e {
  /// < Successful
  static const int CSR_ERROR_NONE = 0;

  /// < Invalid function parameter
  static const int CSR_ERROR_INVALID_PARAMETER = -22;

  /// < Out of memory
  static const int CSR_ERROR_OUT_OF_MEMORY = -12;

  /// < Permission denied
  static const int CSR_ERROR_PERMISSION_DENIED = -13;

  /// < Device needed to run API is not supported
  static const int CSR_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Busy for processing another request
  static const int CSR_ERROR_BUSY = -16;

  /// < Socket error between client and server
  static const int CSR_ERROR_SOCKET = -31653887;

  /// < The given handle is invalid
  static const int CSR_ERROR_INVALID_HANDLE = -31653886;

  /// < Server has been failed for some reason
  static const int CSR_ERROR_SERVER = -31653885;

  /// < No Task exists
  static const int CSR_ERROR_NO_TASK = -31653884;

  /// < DB transaction error
  static const int CSR_ERROR_DB = -31653883;

  /// < Removing file or application is failed
  static const int CSR_ERROR_REMOVE_FAILED = -31653882;

  /// < Getting user response is failed
  static const int CSR_ERROR_USER_RESPONSE_FAILED = -31653881;

  /// < File not exist
  static const int CSR_ERROR_FILE_DO_NOT_EXIST = -31653880;

  /// < File changed after detection
  static const int CSR_ERROR_FILE_CHANGED = -31653879;

  /// < File type is invalid
  static const int CSR_ERROR_FILE_SYSTEM = -31653872;

  /// < Insufficient permission of engine
  static const int CSR_ERROR_ENGINE_PERMISSION = -31653871;

  /// < No engine exists
  static const int CSR_ERROR_ENGINE_NOT_EXIST = -31653870;

  /// < Engine is in disabled state
  static const int CSR_ERROR_ENGINE_DISABLED = -31653869;

  /// < Engine is not activated
  static const int CSR_ERROR_ENGINE_NOT_ACTIVATED = -31653868;

  /// < Engine internal error
  static const int CSR_ERROR_ENGINE_INTERNAL = -31653863;

  /// < System error
  static const int CSR_ERROR_SYSTEM = -31653633;
}

/// @partner
/// @brief Content screening APIs context handle.
