  static const int CALENDAR_TODO_STATUS_COMPLETED = 1024;

  /// < Work in process status
  static const int CALENDAR_TODO_STATUS_IN_PROCESS = 2048;

  /// < Canceled status
  static const int CALENDAR_TODO_STATUS_CANCELED = 4096;
}

/// @brief Enumeration for the time type.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_time_type_e {
  /// < Unix time
  static const int CALENDAR_TIME_UTIME = 0;

  /// < Local time
  static const int CALENDAR_TIME_LOCALTIME = 1;
}

/// @brief Enumeration for the range type.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_range_type_e {
  /// < Range until
  static const int CALENDAR_RANGE_UNTIL = 0;

  /// < Range count
  static const int CALENDAR_RANGE_COUNT = 1;

  /// < No range
  static const int CALENDAR_RANGE_NONE = 2;
}

/// @brief Enumeration for the system type.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_system_type_e {
  /// < Locale's default calendar
  static const int CALENDAR_SYSTEM_NONE = 0;

  /// < Locale's default calendar
  static const int CALENDAR_SYSTEM_GREGORIAN = 1;

  /// < East asian lunisolar calendar
  static const int CALENDAR_SYSTEM_EAST_ASIAN_LUNISOLAR = 2;
}

/// @brief Enumeration for the meeting status.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_meeting_status_e {
  /// < No meeting
  static const int CALENDAR_MEETING_STATUS_NOTMEETING = 0;

  /// < Meeting exists
  static const int CALENDAR_MEETING_STATUS_MEETING = 1;

  /// < Meeting received
  static const int CALENDAR_MEETING_STATUS_RECEIVED = 2;

  /// < Meeting canceled
  static const int CALENDAR_MEETING_STATUS_CANCELED = 3;
}

/// @brief Enumeration for weekdays.
/// @details Same value as UCalendarDaysOfWeek in ICU.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_days_of_week_e {
  /// < Sunday
  static const int CALENDAR_SUNDAY = 1;

  /// < Monday
  static const int CALENDAR_MONDAY = 2;

  /// < Tuesday
  static const int CALENDAR_TUESDAY = 3;

  /// < Wednesday
  static const int CALENDAR_WEDNESDAY = 4;

  /// < Thursday
  static const int CALENDAR_THURSDAY = 5;

  /// < Friday
  static const int CALENDAR_FRIDAY = 6;

  /// < Saturday
  static const int CALENDAR_SATURDAY = 7;
}

/// @brief Enumeration for the modified status of a record.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_record_modified_status_e {
  /// < The record is inserted
  static const int CALENDAR_RECORD_MODIFIED_STATUS_INSERTED = 0;

  /// < The record is updated
  static const int CALENDAR_RECORD_MODIFIED_STATUS_UPDATED = 1;

  /// < The record is deleted
  static const int CALENDAR_RECORD_MODIFIED_STATUS_DELETED = 2;
}

/// @brief The structure of time.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
final class calendar_time_s extends ffi.Struct {
  /// < type
  @ffi.Int32()
  external int type;

  external UnnamedUnion3 time;
}

final class UnnamedUnion3 extends ffi.Union {
  /// < utime
  @ffi.LongLong()
  external int utime;

  external UnnamedStruct7 date;
}

final class UnnamedStruct7 extends ffi.Struct {
  /// < year
  @ffi.Int()
  external int year;

  /// < month
  @ffi.Int()
  external int month;

  /// < mday
  @ffi.Int()
  external int mday;

  /// < hour
  @ffi.Int()
  external int hour;

  /// < minute
  @ffi.Int()
  external int minute;

  /// < second
  @ffi.Int()
  external int second;

  /// < Deprecated since 2.4:leap month
  @ffi.Bool()
  external bool is_leap_month;
}

/// @brief Enumeration for the type of a record.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_record_type_e {
  /// < No record type
  static const int CALENDAR_RECORD_TYPE_NONE = 0;

  /// < Book type
  static const int CALENDAR_RECORD_TYPE_CALENDAR_BOOK = 1;

  /// < Event type
  static const int CALENDAR_RECORD_TYPE_EVENT = 2;

  /// < Todo type
  static const int CALENDAR_RECORD_TYPE_TODO = 3;
}

/// @brief Enumeration for the book mode.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_book_mode_e {
  /// < All modules can read and write records of this calendar_book
  static const int CALENDAR_BOOK_MODE_NONE = 0;

  /// < All modules can only read records of this calendar book
  static const int CALENDAR_BOOK_MODE_RECORD_READONLY = 1;
}

/// @brief Enumeration for the sync event type.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_book_sync_event_type_e {
  /// < This book would not be synced to others except me
  static const int CALENDAR_BOOK_SYNC_EVENT_FOR_ME = 0;

  /// < This book would be synced to everyone and deleted events would be deleted on time
  static const int CALENDAR_BOOK_SYNC_EVENT_FOR_EVERY_AND_DELETE = 1;

  /// < This book would be synced to everyone but deleted events would be retained. Deleted events are removed by calendar_db_clean_after_sync() API
  static const int CALENDAR_BOOK_SYNC_EVENT_FOR_EVERY_AND_REMAIN = 2;
}

