  /// < The CapsLock key is pressed down
  static const int IME_KEY_MASK_CAPSLOCK = 2;

  /// < The Control key is pressed down
  static const int IME_KEY_MASK_CONTROL = 4;

  /// < The Alt key is pressed down
  static const int IME_KEY_MASK_ALT = 8;

  /// < The Meta key is pressed down
  static const int IME_KEY_MASK_META = 16;

  /// < The Win (between Control and Alt) is pressed down
  static const int IME_KEY_MASK_WIN = 32;

  /// < The Hyper key is pressed down
  static const int IME_KEY_MASK_HYPER = 64;

  /// < The NumLock key is pressed down
  static const int IME_KEY_MASK_NUMLOCK = 128;

  /// < Key release event
  static const int IME_KEY_MASK_RELEASED = 32768;
}

