/// @brief Enumeration for error codes.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 2.3.1 @endif
abstract class stt_error_e {
  /// < Successful
  static const int STT_ERROR_NONE = 0;

  /// < Out of Memory
  static const int STT_ERROR_OUT_OF_MEMORY = -12;

  /// < I/O error
  static const int STT_ERROR_IO_ERROR = -5;

  /// < Invalid parameter
  static const int STT_ERROR_INVALID_PARAMETER = -22;

  /// < No answer from the STT service
  static const int STT_ERROR_TIMED_OUT = -1073741823;

  /// < Device or resource busy
  static const int STT_ERROR_RECORDER_BUSY = -16;

  /// < Network is down
  static const int STT_ERROR_OUT_OF_NETWORK = -100;

  /// < Permission denied
  static const int STT_ERROR_PERMISSION_DENIED = -13;

  /// < STT NOT supported
  static const int STT_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Invalid state
  static const int STT_ERROR_INVALID_STATE = -49283071;

  /// < Invalid language
  static const int STT_ERROR_INVALID_LANGUAGE = -49283070;

  /// < No available engine
  static const int STT_ERROR_ENGINE_NOT_FOUND = -49283069;

  /// < Operation failed
  static const int STT_ERROR_OPERATION_FAILED = -49283068;

  /// < Not supported feature of current engine
  static const int STT_ERROR_NOT_SUPPORTED_FEATURE = -49283067;

  /// < Recording timed out @if MOBILE (Since 3.0) @elseif WEARABLE (Since 2.3.2) @endif
  static const int STT_ERROR_RECORDING_TIMED_OUT = -49283066;

  /// < No speech while recording @if MOBILE (Since 3.0) @elseif WEARABLE (Since 2.3.2) @endif
  static const int STT_ERROR_NO_SPEECH = -49283065;

  /// < Progress to ready is not finished @if MOBILE (Since 3.0) @elseif WEARABLE (Since 2.3.2) @endif
  static const int STT_ERROR_IN_PROGRESS_TO_READY = -49283064;

  /// < Progress to recording is not finished @if MOBILE (Since 3.0) @elseif WEARABLE (Since 2.3.2) @endif
  static const int STT_ERROR_IN_PROGRESS_TO_RECORDING = -49283063;

  /// < Progress to processing is not finished @if MOBILE (Since 3.0) @elseif WEARABLE (Since 2.3.2) @endif
  static const int STT_ERROR_IN_PROGRESS_TO_PROCESSING = -49283056;

  /// < Service reset @if MOBILE (Since 3.0) @elseif WEARABLE (Since 2.3.2) @endif
  static const int STT_ERROR_SERVICE_RESET = -49283055;
}

/// @brief Enumeration for state.
