  /// < 'CREATED' state
  static const int STT_STATE_CREATED = 0;

  /// < 'READY' state
  static const int STT_STATE_READY = 1;

  /// < 'RECORDING' state
  static const int STT_STATE_RECORDING = 2;

  /// < 'PROCESSING' state
