  /// < Initialize engine
  external vce_initialize_cb initialize;

  /// < Shutdown engine
  external vce_deinitialize_cb deinitialize;

  /// < Set language
  external vce_set_language_cb set_language;

  /// < Request to set current commands
  external vce_set_commands_cb set_commands;

  /// < Request to unset current commands
  external vce_unset_commands_cb unset_commands;

  /// < Start recognition
  external vce_start_cb start;

  /// < Set recording data
