  /// < Set private data from the app
  external vce_private_data_set_cb private_data_set;

  /// < Send private data to the app
  external vce_private_data_requested_cb private_data_request;

  /// < Send essential value from NLU result
  external vce_nlu_base_info_requested_cb nlu_base_info_request;

  /// < Get specific engine's request from the engine service user
  external vce_specific_engine_request_cb specific_engine_request;
}

